class EventBus {
  constructor() { this.channels = {}; }

  // Subscriber tunes in
  subscribe(channelName, callback) {
    if (!this.channels[channelName]) this.channels[channelName] = [];
    this.channels[channelName].push(callback);
  }

  // Publisher broadcasts
  publish(channelName, data) {
    const channel = this.channels[channelName];
    if (!channel || channel.length === 0) return; // Nobody is listening, do nothing
    channel.forEach(callback => callback(data));
  }
}

const bus = new EventBus();

// Module A: Subscribes
bus.subscribe('USER_LOGIN', user => console.log(`Load Dashboard for ${user}`));
bus.subscribe('USER_LOGIN', user => console.log(`Fetch Cart for ${user}`));

// Module B: Publishes (It doesn't know Module A exists!)
bus.publish('USER_LOGIN', 'Alice');
// Output: Load Dashboard for Alice
// Output: Fetch Cart for Alice
